<body>

    <div id="yaml-data-source" style="display:none;">$1</div>

    <main class="main-container">
        <!-- Top Section -->
        <section class="top-section">
            <div id="status-bar" class="status-bar"></div>
            <div id="inventory" class="inventory"></div>
        </section>

        <!-- Area Section -->
        <details class="collapsible-section" id="area-section-details">
            <summary>区域设施</summary>
            <div class="collapsible-section-content" id="area-section-content"></div>
        </details>

        <!-- Employee Section -->
        <details class="collapsible-section" open id="employee-section-details">
            <summary>员工名录</summary>
            <div class="collapsible-section-content" id="employee-section-content" style="padding: 0.5rem; gap: 1rem;"></div>
        </details>

        <!-- Action Options -->
        <section class="action-options-container">
            <h3>行动选项</h3>
            <ul class="action-list" id="action-list"></ul>
        </section>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
             const triggerQuickReply = (text) => {
                if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
                // In a real SillyTavern environment, this function is provided globally.
                if (typeof triggerSlash === 'function') {
                    const command = `/send ${text}|/trigger`;
                    triggerSlash(command);
                    console.log(`Sent to SillyTavern: ${command}`);
                } else {
                    console.log(`SillyTavern environment not detected. Would trigger command: "${text}"`);
                }
            };

            try {
                const yamlSrc = document.getElementById('yaml-data-source').textContent;
                const data = jsyaml.load(yamlSrc);
                const root = data['面板总览'];

                renderStatus(root['基础信息'], triggerQuickReply);
                renderInventory(root['库存清单']);
                renderAreas(data['区域设施']);
                renderEmployees(data['员工名录']);
                renderActions(data['行动选项']);

                document.querySelectorAll('.action-item').forEach(item => {
                    item.addEventListener('click', () => {
                       triggerQuickReply(item.textContent.trim());
                    });
                });

            } catch (e) {
                console.error("Error rendering UI:", e);
                document.body.innerHTML = `<div style="color:red;padding:20px;border:1px solid red;background:var(--panel-bg);border-radius:1rem;"><strong>UI渲染错误:</strong> ${e.message}.<br><pre>${e.stack}</pre><br>请检查YAML数据格式和内容。</div>`;
            }
        });

        function renderStatus(data, triggerQuickReply) {
            const container = document.getElementById('status-bar');
            if (!data) return;
            const expPercent = (data.玩家等级.当前经验 / data.玩家等级.升级所需) * 100;

            const difficultyMap = { "标准": "standard", "困难": "hard", "地狱": "hell" };
            const difficultyKey = Object.keys(difficultyMap).find(k => (data.难度 || '').includes(k)) || "标准";
            const difficultyClass = `difficulty-${difficultyMap[difficultyKey]}`;

            // 修正：确保能正确读取并处理营业状态，即使数据源存在前后空格或未定义。
            const isInitiallyOpen = (data['营业状态'] || '').trim() === '营业中';
            const initialStatusClass = isInitiallyOpen ? 'open' : 'closed';
            const initialStatusText = isInitiallyOpen ? '营业中' : '休息中';

            container.innerHTML = `
                <div class="top-right-buttons">
                    <div class="status-button business-status ${initialStatusClass}" id="business-status-toggle">${initialStatusText}</div>
                    <div class="status-button ${difficultyClass}">${data.难度}</div>
                </div>
                <div class="status-item">
                    <span class="icon">⏰</span> <span>${data.日期时间}</span>
                </div>
                <div class="status-item">
                    <span class="icon">📍</span> <span>${data.地点}</span>
                </div>
                <div class="status-item">
                    <span class="icon">👑</span>
                    <div style="flex-grow:1;">
                        <span>${data.玩家等级.名称} Lv.${data.玩家等级.等级}</span>
                        <div class="level-progress-bar">
                            <div class="fill" style="width: ${expPercent}%"></div>
                        </div>
                    </div>
                    <span class="level-text">${data.玩家等级.当前经验}/${data.玩家等级.升级所需}</span>
                </div>
            `;

            // 为按钮绑定点击事件，实现状态切换和指令发送
            const businessBtn = container.querySelector('#business-status-toggle');
            if (businessBtn) {
                businessBtn.addEventListener('click', () => {
                    const isOpen = businessBtn.classList.contains('open');
                    if (isOpen) {
                        businessBtn.classList.remove('open');
                        businessBtn.classList.add('closed');
                        businessBtn.textContent = '休息中';
                        triggerQuickReply('停止营业');
                    } else {
                        businessBtn.classList.remove('closed');
                        businessBtn.classList.add('open');
                        businessBtn.textContent = '营业中';
                        triggerQuickReply('开始营业');
                    }
                });
            }
        }

        function renderInventory(data) {
            const container = document.getElementById('inventory');
              if (!data) { container.innerHTML = '<li>无物品</li>'; return; }
            container.innerHTML = data.map(item => `
                <div class="inventory-item">
                    <div class="name">
                        <span class="icon">${item.图标 || ' பொருள'}</span>
                        <span>${item.名称}</span>
                    </div>
                    <span class="quantity">${item.数量}</span>
                </div>
            `).join('');
        }

        function renderAreas(data) {
            const container = document.getElementById('area-section-content');
            if (!data) { container.innerHTML = '<li>无区域</li>'; return; }
            container.style.gridTemplateColumns = 'repeat(auto-fit, minmax(200px, 1fr))';
            container.innerHTML = data.map(areaData => {
                const area = areaData.区域;
                return `
                <details class="area-block">
                    <summary>${area.图标 || '🏢'} ${area.名称}</summary>
                    <div class="area-content">
                        ${(area.设施 || []).map(f => `
                            <div class="facility-item">
                                <span>${f.名称} ${f.数量 ? `x${f.数量}`: ''}</span>
                                <span class="level">Lv.${f.等级}</span>
                            </div>
                        `).join('')}
                    </div>
                </details>
            `;}).join('');
        }

        function renderEmployees(data) {
            const container = document.getElementById('employee-section-content');
            if (!data) { container.innerHTML = '<li>无员工</li>'; return; }
            container.innerHTML = (data || []).map(empData => {
                const e = empData.员工;
                const expPercent = e.经验 ? (e.经验.当前 / e.经验.上限) * 100 : 0;
                const radarSVG = createRadarChart(e.属性);
                return `
                <details class="employee-block">
                    <summary>
                        <div class="employee-summary-content">
                            <div class="employee-name-level">
                                <span class="name">${e.名字} (Lv.${e.综合等级})</span>
                                <span class="rarity rarity-${e.稀有度}">${e.稀有度}</span>
                            </div>
                            <div class="employee-progress-details">
                                <div class="employee-exp-container" title="经验: ${e.经验?.当前 || 0}/${e.经验?.上限 || 100}">
                                    <div class="employee-exp-bar"><div class="fill" style="width: ${expPercent}%"></div></div>
                                </div>
                                <p class="employee-thoughts" title="${e.内心想法}">“${e.内心想法}”</p>
                            </div>
                        </div>
                    </summary>
                    <div class="employee-details">
                        <div class="employee-card">
                            <h4>属性雷达</h4>
                            <div id="radar-chart-container">${radarSVG}</div>
                        </div>
                        <div class="employee-card">
                            <h4>基础情报</h4>
                             <div class="body-data-list">
                                <div class="body-data-item"><span>状态</span><span>${e.状态}</span></div>
                                <div class="body-data-item"><span>忠诚度</span><span>${e.属性?.忠诚 ?? e.好感度}/100</span></div>
                                <div class="body-data-item"><span>接客次数</span><span>${e.接客次数}</span></div>
                                <div class="body-data-item"><span>来源</span><span>${e.来源}</span></div>
                            </div>
                        </div>
                        <div class="employee-card">
                            <h4>掌握技能</h4>
                            <div class="skill-list">
                            ${(e.掌握技能 || []).map(s => `
                                <details class="skill-item">
                                    <summary>
                                        <span>${s.名称} (Lv.${s.等级})</span>
                                        <span class="skill-type">[${s.类型}]</span>
                                    </summary>
                                    <div class="skill-desc">${s.描述 || '暂无详细描述。'}</div>
                                </details>
                            `).join('')}
                            </div>
                        </div>
                        <div class="employee-card">
                            <h4>身体数据</h4>
                            <div class="body-data-list">
                            ${Object.entries(e.身体数据?.受精量 || {}).map(([key, val]) => `<div class="body-data-item"><span>${key}受精量</span> <span>${val}</span></div>`).join('')}
                            </div>
                        </div>
                    </div>
                </details>
                `;
            }).join('');
        }

        function renderActions(data) {
            const container = document.getElementById('action-list');
             if (!data) { container.innerHTML = '<li>无可用行动</li>'; return; }
            container.innerHTML = (data || []).map(action => `<li class="action-item">${action}</li>`).join('');
        }

        function createRadarChart(data, size = 200) {
            if (!data) return '<p style="text-align:center;color:var(--text-muted-color);">无属性数据</p>';
            const filteredData = Object.fromEntries(Object.entries(data).filter(([key]) => key !== '忠诚'));
            const center = size / 2;
            const radius = size * 0.38;
            const labels = Object.keys(filteredData);
            if (labels.length === 0) return '';
            const numAxes = labels.length;
            const angleSlice = (Math.PI * 2) / numAxes;

            let axes = '', axisLabels = '', circles = '';
            for (let i = 0; i < numAxes; i++) {
                const angle = angleSlice * i - Math.PI / 2;
                const x2 = center + radius * Math.cos(angle); const y2 = center + radius * Math.sin(angle);
                axes += `<line x1="${center}" y1="${center}" x2="${x2}" y2="${y2}" stroke="rgba(255,255,255,0.15)" />`;
                const labelX = center + (radius + 20) * Math.cos(angle); const labelY = center + (radius + 20) * Math.sin(angle);
                axisLabels += `<text x="${labelX}" y="${labelY}" dy="0.35em" text-anchor="middle" class="axis-label">${labels[i]}</text>`
            }

            for (let i = 1; i <= 4; i++) {
                circles += `<circle cx="${center}" cy="${center}" r="${(radius/4)*i}" fill="none" stroke="rgba(255,255,255,0.08)" />`;
            }

            const points = labels.map((key, i) => {
                const value = filteredData[key] || 0;
                const angle = angleSlice * i - Math.PI / 2;
                const currentRadius = (value / 100) * radius;
                const x = center + currentRadius * Math.cos(angle); const y = center + currentRadius * Math.sin(angle);
                return `${x},${y}`;
            }).join(' ');

            const pointCircles = labels.map((key, i) => {
                const value = filteredData[key] || 0;
                const angle = angleSlice * i - Math.PI / 2;
                const currentRadius = (value / 100) * radius;
                const x = center + currentRadius * Math.cos(angle); const y = center + currentRadius * Math.sin(angle);
                return `<circle cx="${x}" cy="${y}" r="3" fill="#00e5ff" />`
            }).join('');

            return `
                <svg viewBox="0 0 ${size} ${size}" class="radar-chart">
                    <g class="grid">${circles}${axes}</g>
                    <g class="labels">${axisLabels}</g>
                    <polygon points="${points}" fill="rgba(0, 229, 255, 0.4)" stroke="#00e5ff" stroke-width="2" />
                    <g class="points">${pointCircles}</g>
                </svg>
            `;
        }
    </script>
</body>
</html>
