        /* --- RARITY OVERHAUL --- */
        .rarity { display: inline-block; padding: 3px 10px; border-radius: 4px; font-size: 0.7rem; font-weight: bold; line-height: 1; transition: transform 0.3s ease, box-shadow 0.3s ease; cursor: default; position: relative; overflow: hidden; z-index: 1; }
